import{_ as e,o as t,c as s,a4 as n}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"HomeSense v3 交接文档","description":"","frontmatter":{"title":"HomeSense v3 交接文档","date":"2026-08-29T00:00:00.000Z"},"headers":[],"relativePath":"posts/HomeSense-v3-交接文档.md","filePath":"posts/HomeSense-v3-交接文档.md"}'),i={name:"posts/HomeSense-v3-交接文档.md"};function o(l,a,d,r,c,h){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="homesense-v3-交接文档" tabindex="-1">HomeSense v3 交接文档 <a class="header-anchor" href="#homesense-v3-交接文档" aria-label="Permalink to &quot;HomeSense v3 交接文档&quot;">​</a></h1><blockquote><p>写给下一个接手的人。读完这份文档,你应该知道:项目是什么、做到哪了、已定案什么决策、代码在哪、下一步干什么。</p><p>状态: 架构定案完成,尚未开始写代码 (Phase 0 ✅ / Phase 1 未开始)</p></blockquote><hr><h2 id="一、项目是什么" tabindex="-1">一、项目是什么 <a class="header-anchor" href="#一、项目是什么" aria-label="Permalink to &quot;一、项目是什么&quot;">​</a></h2><p><strong>HomeSense = 云边协同的智能家居 AI 管家 SaaS。</strong></p><p>一个 Android/iOS 电视盒子控制项目演化而来,核心能力是:用户说一句话(&quot;打开电视看B站&quot;),云端 Agent 理解意图,家里的边缘盒子执行(ADB/miio 控制路由器、电视、投影仪、智能家居设备)。</p><h3 id="一句话价值主张" tabindex="-1">一句话价值主张 <a class="header-anchor" href="#一句话价值主张" aria-label="Permalink to &quot;一句话价值主张&quot;">​</a></h3><blockquote><p>用户什么都不会(不懂 adb、不懂 miio、不懂配网),产品要让他插上盒子、扫码、对话,就能控制家里所有设备。断网也能用基础功能。</p></blockquote><h3 id="产品形态-saas-硬件混合" tabindex="-1">产品形态(SaaS + 硬件混合) <a class="header-anchor" href="#产品形态-saas-硬件混合" aria-label="Permalink to &quot;产品形态(SaaS + 硬件混合)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>云端 SaaS: Agent 大脑(复杂推理/记忆/多设备统筹) —— 订阅费是收入核心</span></span>
<span class="line"><span>边缘盒子: 即插即用(主动连云端/本地规则/断网降级) —— 硬件是入口和留存</span></span>
<span class="line"><span>App/Web:  极简界面,用户只看到 &quot;对话 + 按钮&quot;</span></span></code></pre></div><hr><h2 id="二、仓库状态" tabindex="-1">二、仓库状态 <a class="header-anchor" href="#二、仓库状态" aria-label="Permalink to &quot;二、仓库状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>工作仓库</td><td><code>/mnt/shared/HomeSense-Studio-v3</code></td></tr><tr><td>当前分支</td><td><code>main</code></td></tr><tr><td>最近提交</td><td>架构文档(2026-08-29,约15条 docs(v3) 提交)</td></tr><tr><td>文档位置</td><td><code>docs/v3/ARCHITECTURE.md</code> (核心,先读它)</td></tr><tr><td>旧版归档</td><td>v1/v2 全部压缩在 <code>origin/archive/v2-main</code>, <code>origin/v1.0-master</code>, <code>origin/source/*</code> 分支</td></tr></tbody></table><p>⚠️ <strong>注意</strong>:仓库挂载在 NFS (<code>192.168.31.82:/mnt/shared</code>),git 操作要小心跨文件系统问题。大仓库克隆用 codeload tarball,不要 git clone(浪费流量)。</p><hr><h2 id="三、已定案的架构决策-全部写进-docs-v3-architecture-md" tabindex="-1">三、已定案的架构决策 (全部写进 docs/v3/ARCHITECTURE.md) <a class="header-anchor" href="#三、已定案的架构决策-全部写进-docs-v3-architecture-md" aria-label="Permalink to &quot;三、已定案的架构决策 (全部写进 docs/v3/ARCHITECTURE.md)&quot;">​</a></h2><h3 id="_3-1-技术栈" tabindex="-1">3.1 技术栈 <a class="header-anchor" href="#_3-1-技术栈" aria-label="Permalink to &quot;3.1 技术栈&quot;">​</a></h3><ul><li><strong>Next.js 16 (App Router) 全栈</strong> — 前后端一体,API Routes 做后端(用户明确拒绝 NestJS,不要再提)</li><li><strong>React 19 + shadcn/ui + Tailwind v4 + @tabler/icons</strong> — UI 模仿 PicoClaw 风格(简约好用)</li><li><strong>SQLite(Node better-sqlite3)</strong> 一租户一个 <code>.db</code> 文件,物理隔离</li><li><strong>WebSocket</strong> 云端↔盒子长连接(盒子主动出站,NAT 反向穿透,无需公网IP)</li><li><strong>LangGraph + Vercel AI SDK</strong> — Agent 层(DeepSeek/OpenAI 可切换)</li><li>类型校验 TypeBox</li></ul><h3 id="_3-2-多租户-saas-核心" tabindex="-1">3.2 多租户(SaaS 核心) <a class="header-anchor" href="#_3-2-多租户-saas-核心" aria-label="Permalink to &quot;3.2 多租户(SaaS 核心)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>/home/homesense/data/</span></span>
<span class="line"><span>  ├── tenant_1.db    # 每个用户一个独立文件</span></span>
<span class="line"><span>  ├── tenant_2.db</span></span>
<span class="line"><span>  └── ...</span></span></code></pre></div><ul><li>路由层按 token 分发到对应文件</li><li>备份 = <code>cp 文件</code>;销毁 = 删文件;零耦合</li><li><strong>禁止 per-user 容器</strong>(100用户=300容器必炸)</li><li>单文件&gt;100MB 或租户&gt;10000 才考虑换 Postgres(大概率不会触发)</li></ul><h3 id="_3-3-云边协同" tabindex="-1">3.3 云边协同 <a class="header-anchor" href="#_3-3-云边协同" aria-label="Permalink to &quot;3.3 云边协同&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>用户(任意网络) ──WebSocket──▶ 云端SaaS(大脑) ──WebSocket──▶ 家里盒子(手脚) ──▶ 设备</span></span>
<span class="line"><span>   App/Web                      多租户Agent服务               ADB/miio/蓝牙      电视/灯/空调</span></span></code></pre></div><ul><li><strong>盒子永远主动连云端(出站),绝不接收入站</strong> — 这是&quot;用户在外能控家&quot;的解法</li><li>云端:复杂推理/记忆/跨设备统筹</li><li>盒子:本地规则/即时响应/断网降级/隐私</li><li>盒子 = ADB 的代理,真正的 adb 命令在盒子上跑</li></ul><h3 id="_3-4-产品-多租户-agent-服务-基础设施不暴露" tabindex="-1">3.4 产品=多租户 Agent 服务,基础设施不暴露 <a class="header-anchor" href="#_3-4-产品-多租户-agent-服务-基础设施不暴露" aria-label="Permalink to &quot;3.4 产品=多租户 Agent 服务,基础设施不暴露&quot;">​</a></h3><ul><li>用户接触:App/Web → Agent → LLM → 结果</li><li>n8n/HA/Postgres 等是内部工具,用户看不见摸不着</li><li>自由版(1盒子/基础功能) → Pro版(¥29/月) → 企业版(私有化)</li></ul><h3 id="_3-5-巨人肩膀原则" tabindex="-1">3.5 巨人肩膀原则 <a class="header-anchor" href="#_3-5-巨人肩膀原则" aria-label="Permalink to &quot;3.5 巨人肩膀原则&quot;">​</a></h3><ul><li>用库/官方包 90%(miio、adbkit、shadcn、React Flow、n8n自用)</li><li>自己写 10%: 云端编排层 + 账号 + 设备 JSON 模型</li><li>❌ 不裁剪任何人源码(教训: v2 裁剪 n8n 源码是最大的坑)</li><li>⚠️ 商业红线: n8n 免费版禁止打包进商业 SaaS(SUPL 许可证)</li></ul><hr><h2 id="四、v2-留下的资产-可以搬-不要重写" tabindex="-1">四、v2 留下的资产(可以搬,不要重写) <a class="header-anchor" href="#四、v2-留下的资产-可以搬-不要重写" aria-label="Permalink to &quot;四、v2 留下的资产(可以搬,不要重写)&quot;">​</a></h2><p>v2 在 <code>origin/archive/v2-main</code> 分支,大量自研代码可以直接复用:</p><h3 id="后端核心模块-studio-v1-packages-backend-src-modules" tabindex="-1">后端核心模块 (studio-v1/packages/backend/src/modules/) <a class="header-anchor" href="#后端核心模块-studio-v1-packages-backend-src-modules" aria-label="Permalink to &quot;后端核心模块 (studio-v1/packages/backend/src/modules/)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>行数</th><th>内容</th></tr></thead><tbody><tr><td>workflow</td><td>~7200行</td><td>自研轻量工作流引擎(v1替代n8n的底子)</td></tr><tr><td>chat</td><td>~3800行</td><td>会话系统</td></tr><tr><td>device</td><td>~2650行</td><td>设备 JSON 孪生</td></tr><tr><td>memory-kernel</td><td>~2100行</td><td>记忆内核</td></tr><tr><td>intent-router</td><td>~640行</td><td>意图路由(顶层编排雏形)</td></tr><tr><td>rule-engine</td><td>~830行</td><td>规则引擎</td></tr><tr><td>skills-system</td><td>~435行</td><td>技能系统</td></tr><tr><td>executor-gateway</td><td>~434行</td><td>执行器网关</td></tr></tbody></table><h3 id="协议层-最值钱-别人写不出" tabindex="-1">协议层(最值钱,别人写不出) <a class="header-anchor" href="#协议层-最值钱-别人写不出" aria-label="Permalink to &quot;协议层(最值钱,别人写不出)&quot;">​</a></h3><ul><li><code>packages/mi-cli</code> (~4000行) — 完整米家协议: auth/设备/IR/场景/音箱/能力字典</li><li><code>packages/adb-cli</code> (~2200行) — ADB 电视控制</li><li><code>packages/media-cli</code> (~2200行) — 媒体/投屏</li></ul><h3 id="已死的资产-直接丢弃-别复活" tabindex="-1">已死的资产(直接丢弃,别复活) <a class="header-anchor" href="#已死的资产-直接丢弃-别复活" aria-label="Permalink to &quot;已死的资产(直接丢弃,别复活)&quot;">​</a></h3><ul><li>❌ n8n 源码裁剪 (n8n-runtime-trim) — 许可证+维护地狱</li><li>❌ HomeCast 投屏自研系统 — 用现成 dlna</li><li>❌ 多余的 Python CLI 壳 (cli/adb, cli/hami) — 用库</li><li>❌ 四套前端 — 只留 one shadcn 前端</li></ul><hr><h2 id="五、下一步-phase-1-monorepo-骨架-云端核心" tabindex="-1">五、下一步(Phase 1: monorepo 骨架 + 云端核心) <a class="header-anchor" href="#五、下一步-phase-1-monorepo-骨架-云端核心" aria-label="Permalink to &quot;五、下一步(Phase 1: monorepo 骨架 + 云端核心)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>HomeSense-Studio-v3/</span></span>
<span class="line"><span>  apps/</span></span>
<span class="line"><span>    web/        # Next.js 前端 + API Routes</span></span>
<span class="line"><span>    hub/        # 边缘盒子轻量进程 (Node.js)</span></span>
<span class="line"><span>  packages/</span></span>
<span class="line"><span>    device/     # 设备 JSON 模型 + CAPABILITY_REGISTRY</span></span>
<span class="line"><span>    agent/      # 顶层编排 + 角色路由</span></span>
<span class="line"><span>    workflow/   # 从 v2 workflow 模块搬来</span></span>
<span class="line"><span>    memory/     # 从 v2 memory-kernel 搬来</span></span>
<span class="line"><span>    protocol/   # TypeBox 协议</span></span>
<span class="line"><span>    db/         # SQLite 租户路由层</span></span>
<span class="line"><span>  docs/v3/      # 架构文档</span></span></code></pre></div><p><strong>第一个里程碑</strong>:本地跑通 PicoClaw 风格 UI 骨架 + 一个&quot;对话→Agent→模拟执行设备&quot;的最小闭环。</p><hr><h2 id="六、环境与开发注意事项" tabindex="-1">六、环境与开发注意事项 <a class="header-anchor" href="#六、环境与开发注意事项" aria-label="Permalink to &quot;六、环境与开发注意事项&quot;">​</a></h2><h3 id="网络-npm-安装" tabindex="-1">网络(npm 安装) <a class="header-anchor" href="#网络-npm-安装" aria-label="Permalink to &quot;网络(npm 安装)&quot;">​</a></h3><ul><li>npm registry: <code>https://registry.npmmirror.com</code></li><li>代理: <code>http://127.0.0.1:7897</code>(Clash Verge 混合端口,不是 7890)</li><li>曾踩坑: 大仓库 git clone 浪费 306MB;用 codeload tarball 只拉最新代码</li></ul><h3 id="参考项目-已研究" tabindex="-1">参考项目(已研究) <a class="header-anchor" href="#参考项目-已研究" aria-label="Permalink to &quot;参考项目(已研究)&quot;">​</a></h3><ul><li><strong>PicoClaw UI</strong>: <code>/tmp/picoclaw-main/web/frontend</code> — React 19 + shadcn/ui + TanStack Router,UI 风格来源(174源文件,14路由,21 shadcn组件)</li><li><strong>OpenClaw 架构</strong>: <code>/mnt/shared/openclaw</code> — 网关/记忆/多通道路由思想来源(UI太重用它的,不用它UI)</li><li><strong>pi-web</strong>: <code>/mnt/shared/pi-web-study</code> — 可运行参考,Next.js 16 已验证可以在本机跑</li></ul><h3 id="开发节奏-用户的血泪教训" tabindex="-1">开发节奏(用户的血泪教训) <a class="header-anchor" href="#开发节奏-用户的血泪教训" aria-label="Permalink to &quot;开发节奏(用户的血泪教训)&quot;">​</a></h3><ol><li>用户痛恨&quot;太重太慢&quot;,要<strong>快速看到可运行的东西</strong></li><li>不重写已有资产,搬运+整合</li><li>界面要<strong>极简</strong>,用户(和面试官)看的都是演示效果</li><li>用户的核心诉求: <strong>能演示、能上简历、能装逼</strong></li></ol><hr><h2 id="七、用户画像-接手人必读" tabindex="-1">七、用户画像(接手人必读) <a class="header-anchor" href="#七、用户画像-接手人必读" aria-label="Permalink to &quot;七、用户画像(接手人必读)&quot;">​</a></h2><ul><li>单干开发者,有 v1/v2 两代智能家居项目经验(44个模块)</li><li>情绪化,容易焦虑(&quot;太难了&quot; &quot;放弃&quot;),但方向感强</li><li><strong>要什么</strong>: 一个能跑、能演示、技术有深度的项目,能写进简历</li><li><strong>怕什么</strong>: 复杂到跑不起来、又要重写、浪费时间</li><li>沟通建议: 少讨论多动手,先出可运行原型,再聊架构</li></ul><hr><h2 id="附-常见问题速答" tabindex="-1">附:常见问题速答 <a class="header-anchor" href="#附-常见问题速答" aria-label="Permalink to &quot;附:常见问题速答&quot;">​</a></h2><p><strong>Q: 用户不会配盒子怎么用?</strong> A: 出厂预配置好,插电+扫码配对(像连WiFi),之后全是对话。</p><p><strong>Q: 用户在外面怎么控制家里?</strong> A: 盒子主动连云端(WebSocket 出站),App连云端,云端转发指令。无需公网IP/端口映射。</p><p><strong>Q: 为什么不用 Postgres?</strong> A: 规模不到。SQLite 一租户一文件,简单够用,备份即复制。真到了1万租户再换。</p><p><strong>Q: 为什么不用 n8n 商业版?</strong> A: 自用(开发/家庭)用 n8n 没问题;打包进商业SaaS 违反 SUPL 许可证。自己的 workflow 引擎已有底子(v2 7200行)。</p><p><strong>Q: Agent 放盒子还是云?</strong> A: 两层都放。云=大脑(推理/记忆),盒子=手脚(执行/断网降级)。</p>`,59)])])}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
